function applyGymIdentity(){document.querySelectorAll('.entry-logo').forEach(el=>{el.innerHTML='<img src="assets/energy-plus-logo.png" alt="لوجو Energy Club — الدراع الدهبي"><b>ENERGY CLUB<small>STAFF MANAGEMENT</small></b>'});document.querySelectorAll('.brand').forEach(el=>{el.innerHTML='<img src="assets/energy-plus-logo.png" alt="Energy Club"><span>ENERGY CLUB<small>STAFF MANAGEMENT</small></span>';el.setAttribute('aria-label','Energy Club — الرئيسية')});document.querySelectorAll('.entry-brand-mobile').forEach(el=>el.innerHTML='<img src="assets/energy-plus-logo.png" alt="Energy Club"><span>ENERGY CLUB • STAFF</span>');document.querySelectorAll('.report-brand>div:first-child').forEach(el=>{if(!el.querySelector('img'))el.insertAdjacentHTML('afterbegin','<img src="assets/energy-plus-logo.png" alt="Energy Club">')})}
const identityRender=render,identityEntryView=entryView;render=function(){identityRender();applyGymIdentity()};entryView=function(){identityEntryView();applyGymIdentity()};applyGymIdentity();
